SELECT percentile_cont(0.75) within GROUP (ORDER BY AVG(labevents.value)) AS percentile FROM labevents JOIN icustays ON labevents.subject_id = icustays.subject_id JOIN patients ON icustays.subject_id = patients.subject_id WHERE labevents.itemid = 84807 AND EXTRACT(YEAR FROM age(CURRENT_DATE, patients.dob)) BETWEEN 75 AND 85 AND icustays.first_careunit = 'ICU' AND icustays.intime <= '00:00' AND icustays.outtime >= '23:59' AND EXTRACT(HOUR FROM (icustays.outtime - icustays.intime)) <= 48 AND labevents.value <= 140;